import { DiscourseNode, DiscourseRelationType, Settings } from "~/types";
import generateUid from "~/utils/generateUid";

const now = new Date().getTime();

export const DEFAULT_NODE_TYPES: Record<string, DiscourseNode> = {
  question: {
    id: generateUid("node"),
    name: "Question",
    format: "QUE - {content}",
    color: "#99890e",
    created: now,
    modified: now,
  },
  claim: {
    id: generateUid("node"),
    name: "Claim",
    format: "CLM - {content}",
    color: "#7DA13E",
    tag: "clm-candidate",
    created: now,
    modified: now,
  },
  evidence: {
    id: generateUid("node"),
    name: "Evidence",
    format: "EVD - {content}",
    color: "#DB134A",
    tag: "evd-candidate",
    created: now,
    modified: now,
  },
  source: {
    id: generateUid("node"),
    name: "Source",
    format: "SRC - {content}",
    color: "#9E9E9E",
    tag: "src-candidate",
    created: now,
    modified: now,
  },
};
export const DEFAULT_RELATION_TYPES: Record<string, DiscourseRelationType> = {
  supports: {
    id: generateUid("relation"),
    label: "supports",
    complement: "is supported by",
    color: "green",
    created: now,
    modified: now,
  },
  opposes: {
    id: generateUid("relation"),
    label: "opposes",
    complement: "is opposed by",
    color: "red",
    created: now,
    modified: now,
  },
  informs: {
    id: generateUid("relation"),
    label: "informs",
    complement: "is informed by",
    color: "grey",
    created: now,
    modified: now,
  },
  derivedFrom: {
    id: generateUid("relation"),
    label: "derived from",
    complement: "has derivation",
    color: "blue",
    created: now,
    modified: now,
  },
};

export const DEFAULT_SETTINGS: Settings = {
  nodeTypes: Object.values(DEFAULT_NODE_TYPES),
---
5:export type DiscourseNode = {
11:  shortcut?: string;
13:  tag?: string;
70:  nodeTagHotkey: string;

1	import {
2	  App,
3	  Component,
4	  MarkdownRenderer,
5	  Modal,
6	  Notice,
7	  renderResults,
8	  TFile,
9	  type SearchResult,
10	} from "obsidian";
11	import {
12	  StrictMode,
13	  useEffect,
14	  useMemo,
15	  useRef,
16	  useState,
17	  type KeyboardEvent,
18	  type MouseEvent,
19	  type ReactElement,
20	} from "react";
21	import { createRoot, Root } from "react-dom/client";
22	import type DiscourseGraphPlugin from "~/index";
23	import { NodeSearchFooter } from "~/components/NodeSearchFooter";
24	import { NodeSortMenu } from "~/components/NodeSortMenu";
25	import { NodeTypeChipsSearchInput } from "~/components/NodeTypeChipsSearchInput";
26	import { NodeTypeFilterMenu } from "~/components/NodeTypeFilterMenu";
27	import type { SearchDropdownId } from "~/components/SearchDropdown";
28	import {
29	  openFileInNewLeaf,
30	  openFileInNewTab,
31	} from "~/components/canvas/utils/openFileUtils";
32	import {
33	  insertLinkAtInsertTarget,
34	  snapshotInsertTarget,
35	  type EditorInsertTarget,
36	} from "~/utils/editorInsertTarget";
37	import {
38	  QueryEngine,
39	  rankDiscourseNodesByTitle,
40	  type DiscourseNodeCandidate,
41	  type RankedDiscourseNode,
42	} from "~/services/QueryEngine";
43	import {
44	  getNodeTypeBadge,
45	  getFallbackNodeTypeBadge,
46	  type NodeTypeBadge,
47	} from "~/utils/nodeTypeBadge";
48	import {
49	  buildAuthorNameByPath,
50	  resolveAuthorName,
51	  useAuthorNames,
52	} from "~/utils/discourseNodeAuthor";
53	import {
54	  DEFAULT_SORT_DIRECTION,
55	  DEFAULT_SORT_KEY,
56	  sortSearchResults,
57	  type SortDirection,
58	  type SortKey,
59	} from "~/utils/discourseNodeSort";
60	
61	const MAX_VISIBLE_RESULTS = 50;
62	const SEARCH_DEBOUNCE_MS = 250;
63	
64	type CandidateState =
65	  | { status: "loading" }
66	  | { status: "ready"; candidates: DiscourseNodeCandidate[] }
67	  | { status: "error"; message: string };
68	
69	type NodeTypeDisplay = {
70	  name: string;
71	  /** Null when neither the config nor the title says what type this is. */
72	  badge: NodeTypeBadge | null;
73	};
74	
75	type SearchResultRow = RankedDiscourseNode & {
76	  nodeType: NodeTypeDisplay;
77	};
78	
79	const formatTimestamp = (epochMs: number): string =>
80	  new Date(epochMs).toLocaleString(undefined, {
81	    dateStyle: "medium",
82	    timeStyle: "short",
83	  });
84	
85	const PreviewPane = ({
86	  app,
87	  result,
88	  authorName,
89	}: {
90	  app: App;
91	  result: SearchResultRow | undefined;
92	  authorName: string;
93	}): ReactElement => {
94	  const containerRef = useRef<HTMLDivElement | null>(null);
95	  // Paired with its file so an in-flight read can't put one note's body under
96	  // another note's title.
97	  const [loaded, setLoaded] = useState<{ file: TFile; text: string } | null>(
98	    null,
99	  );
100	
101	  const file = result?.file;
102	
103	  useEffect(() => {
104	    if (!file) {
105	      setLoaded(null);
106	      return;
107	    }
108	    let cancelled = false;
109	    void app.vault.cachedRead(file).then((text) => {
110	      if (!cancelled) setLoaded({ file, text });
111	    });
112	    return () => {
113	      cancelled = true;
114	    };
115	  }, [app, file]);
116	
117	  useEffect(() => {
118	    const container = containerRef.current;
119	    if (!container || !file || loaded?.file !== file) return;
120	
121	    container.empty();
122	    const component = new Component();
123	    void MarkdownRenderer.render(
124	      app,
125	      loaded.text.trim() || "This note is empty.",
126	      container,
127	      file.path,
128	      component,
129	    );
130	
131	    return () => {
132	      component.unload();
133	      container.empty();
134	    };
135	  }, [app, file, loaded]);
136	
137	  if (!result || !file) {
138	    return (
139	      <div className="text-muted flex flex-1 items-center justify-center">
140	        Select a result to preview it.
141	      </div>
142	    );
143	  }
144	
145	  return (
146	    <div className="flex flex-1 flex-col overflow-hidden">
147	      <div className="border-modifier-border border-b px-4 py-3">
148	        <div className="text-normal font-semibold">{result.title}</div>
149	        <div className="text-muted mt-1 text-xs">
150	          {`Created ${formatTimestamp(file.stat.ctime)} · Modified ${formatTimestamp(
151	            file.stat.mtime,
152	          )} · ${authorName}`}
153	        </div>
154	      </div>
155	      <div
156	        ref={containerRef}
157	        className="text-normal flex-1 overflow-y-auto px-4 py-3"
158	      />
159	    </div>
160	  );
161	};
162	
163	const HighlightedTitle = ({
164	  title,
165	  match,
166	}: {
167	  title: string;
168	  match: SearchResult;
169	}): ReactElement => {
170	  const titleRef = useRef<HTMLDivElement | null>(null);
171	
172	  useEffect(() => {
173	    const container = titleRef.current;
174	    if (!container) return;
175	    container.empty();
176	    renderResults(container, title, match);
177	    return () => container.empty();
178	  }, [title, match]);
179	
180	  return (
181	    <div
182	      ref={titleRef}
183	      className="dg-search-result-title text-normal min-w-0 flex-1 truncate"
184	    />
185	  );
186	};
187	
188	const ResultList = ({
189	  results,
190	  activeIndex,
191	  onActivate,
192	}: {
193	  results: SearchResultRow[];
194	  activeIndex: number;
195	  onActivate: (index: number) => void;
196	}): ReactElement => {
197	  const listRef = useRef<HTMLDivElement | null>(null);
198	  const pointerPositionRef = useRef<{ x: number; y: number } | null>(null);
199	
200	  useEffect(() => {
201	    const active = listRef.current?.children[activeIndex];
202	    active?.scrollIntoView({ block: "nearest" });
203	  }, [activeIndex]);
204	
205	  // Scrolling drags rows under a stationary cursor, and the mouseenter that
206	  // fires is not a choice. Compare coordinates rather than resetting a flag on
207	  // every activation, so hovering from row to row still counts as a choice.
208	  const hasPointerMoved = (event: MouseEvent<HTMLDivElement>): boolean => {
209	    const previous = pointerPositionRef.current;
210	    pointerPositionRef.current = { x: event.clientX, y: event.clientY };
211	    return (
212	      previous === null ||
213	      previous.x !== event.clientX ||
214	      previous.y !== event.clientY
215	    );
216	  };
217	
218	  return (
219	    // No `aria-label` here: Obsidian renders one as a hover tooltip, which
220	    // covers the results the moment the pointer enters the list.
221	    <div
222	      ref={listRef}
223	      role="listbox"
224	      onMouseMove={(event) => {
225	        hasPointerMoved(event);
226	      }}
227	      className="flex-1 overflow-y-auto"
228	    >
229	      {results.map((result, index) => (
230	        <div
231	          key={result.file.path}
232	          role="option"
233	          aria-selected={index === activeIndex}
234	          onMouseEnter={(event) => hasPointerMoved(event) && onActivate(index)}
235	          onClick={() => onActivate(index)}
236	          // Keeps focus in the search input, so the keyboard path stays live
237	          // after a click.
238	          onMouseDown={(event) => event.preventDefault()}
239	          className={`border-modifier-border flex cursor-pointer items-center gap-2 border-b px-3 py-2 ${
240	            index === activeIndex ? "bg-modifier-hover" : ""
241	          }`}
242	        >
243	          {result.nodeType.badge && (
244	            <span
245	              aria-label={result.nodeType.name}
246	              style={{
247	                backgroundColor: result.nodeType.badge.backgroundColor,
248	                color: result.nodeType.badge.textColor,
249	              }}
250	              className="shrink-0 rounded-full px-2 py-0.5 text-xs font-semibold"
251	            >
252	              {result.nodeType.badge.text}
253	            </span>
254	          )}
255	          <HighlightedTitle title={result.title} match={result.match} />
256	        </div>
257	      ))}
258	    </div>
259	  );
260	};
261	
262	const NodeSearch = ({
263	  plugin,
264	  insertTarget,
265	  onClose,
266	}: {
267	  plugin: DiscourseGraphPlugin;
268	  insertTarget: EditorInsertTarget | null;
269	  onClose: () => void;
270	}): ReactElement => {
271	  const { app } = plugin;
272	  const [candidateState, setCandidateState] = useState<CandidateState>({
273	    status: "loading",
274	  });
275	  const [query, setQuery] = useState("");
276	  const [debouncedQuery, setDebouncedQuery] = useState("");
277	  const [activeIndex, setActiveIndex] = useState(0);
278	  // Single source of truth: ENG-2111's tag chips will read and write this too.
279	  const [selectedNodeTypeIds, setSelectedNodeTypeIds] = useState<string[]>([]);
280	  // One value per toolbar, so two panels can never be open at once.
281	  const [openDropdown, setOpenDropdown] = useState<SearchDropdownId>(null);
282	  const [sortKey, setSortKey] = useState<SortKey>(DEFAULT_SORT_KEY);
283	  const [sortDirection, setSortDirection] = useState<SortDirection>(
284	    DEFAULT_SORT_DIRECTION,
285	  );
286	  // An editable span, so the query shares its line boxes with the filter chips.
287	  const inputRef = useRef<HTMLSpanElement | null>(null);
288	  const userNames = useAuthorNames({
289	    app,
290	    plugin,
291	    candidates:
292	      candidateState.status === "ready" ? candidateState.candidates : null,
293	  });
294	
295	  const nodeTypesById = useMemo(() => {
296	    const byId = new Map<string, NodeTypeDisplay>();
297	    plugin.settings.nodeTypes.forEach((nodeType, nodeIndex) => {
298	      byId.set(nodeType.id, {
299	        name: nodeType.name,
300	        badge: getNodeTypeBadge({ nodeType, nodeIndex }),
301	      });
302	    });
303	    return byId;
304	  }, [plugin.settings.nodeTypes]);
305	
306	  useEffect(() => {
307	    inputRef.current?.focus();
308	  }, []);
309	
310	  // The fetch is synchronous today, so there is nothing to await or cancel yet.
311	  // Effects run after paint, so the loading state still renders for a frame; if
312	  // this ever becomes a network call, only this body changes.
313	  useEffect(() => {
314	    try {
315	      const candidates = new QueryEngine(app).getDiscourseNodeCandidates();
316	      setCandidateState({ status: "ready", candidates });
317	    } catch (error) {
318	      const message =
319	        error instanceof Error ? error.message : "Unexpected error";
320	      new Notice(`Could not load discourse nodes: ${message}`);
321	      setCandidateState({ status: "error", message });
322	    }
323	  }, [app]);
324	
325	  useEffect(() => {
326	    const timeout = window.setTimeout(
327	      () => setDebouncedQuery(query),
328	      SEARCH_DEBOUNCE_MS,
329	    );
330	    return () => window.clearTimeout(timeout);
331	  }, [query]);
332	
333	  // Sort before truncating, so a date or alphabetical sort covers every match.
334	  const results = useMemo<SearchResultRow[]>(() => {
335	    if (candidateState.status !== "ready") return [];
336	    const ranked = rankDiscourseNodesByTitle({
337	      candidates: candidateState.candidates,
338	      query: debouncedQuery,
339	      nodeTypeIds: selectedNodeTypeIds,
340	    });
341	    const authorNameByPath =
342	      sortKey === "author"
343	        ? buildAuthorNameByPath({
344	            app,
345	            files: ranked.map((result) => result.file),
346	            userNames,
347	          })
348	        : undefined;
349	    return sortSearchResults({
350	      results: ranked,
351	      sortKey,
352	      direction: sortDirection,
353	      authorNameByPath,
354	    })
355	      .slice(0, MAX_VISIBLE_RESULTS)
356	      .map((result) => ({
357	        ...result,
358	        nodeType: nodeTypesById.get(result.nodeTypeId) ?? {
359	          name: "Unknown type",
360	          badge: getFallbackNodeTypeBadge(result.title),
361	        },
362	      }));
363	  }, [
364	    app,
365	    candidateState,
366	    debouncedQuery,
367	    nodeTypesById,
368	    selectedNodeTypeIds,
369	    sortDirection,
370	    sortKey,
371	    userNames,
372	  ]);
373	
374	  // A narrowing query rebuilds `results` before the effect below can reset the
375	  // state, so the old index can point past the new list for one render. Clamping
376	  // here keeps the preview and the highlighted row from blanking for that frame.
377	  const activeIndexInRange = activeIndex < results.length ? activeIndex : 0;
378	  const activeResult = results[activeIndexInRange];
379	
380	  // Only the preview shows an author, so resolve the selection, not all 50 rows.
381	  const authorName = useMemo(
382	    () =>
383	      activeResult
384	        ? resolveAuthorName({ app, file: activeResult.file, userNames })
385	        : "",
386	    [app, activeResult, userNames],
387	  );
388	
389	  useEffect(() => {
390	    setActiveIndex(0);
391	  }, [results]);
392	
393	  const moveActiveIndex = (delta: number) => {
394	    if (!results.length) return;
395	    setActiveIndex((current) => {
396	      const next = current + delta;
397	      if (next < 0) return 0;
398	      if (next > results.length - 1) return results.length - 1;
399	      return next;
400	    });
401	  };
402	
403	  // Closes before opening: `close()` unmounts this React root, so the file and
404	  // app are read first and nothing touches state afterwards.
405	  const openActiveResult = (
406	    open: (app: App, file: TFile) => Promise<void>,
407	  ): void => {
408	    if (!activeResult) return;
409	    const { file } = activeResult;
410	    onClose();
411	    void open(app, file).catch((error: unknown) => {
412	      const message = error instanceof Error ? error.message : String(error);
413	      new Notice(`Could not open ${file.basename}: ${message}`);
414	    });
415	  };
416	
417	  const handleDropdownOpenChange = ({
418	    id,
419	    isOpen,
420	  }: {
421	    id: NonNullable<SearchDropdownId>;
422	    isOpen: boolean;
423	  }): void => {
424	    setOpenDropdown(isOpen ? id : null);
425	    // Returns the keyboard path to the results the moment the panel closes.
426	    if (!isOpen) inputRef.current?.focus();
427	  };
428	
429	  // Closes before inserting, like `openActiveResult`.
430	  const insertLinkToActiveResult = (): void => {
431	    if (!activeResult || !insertTarget) return;
432	    const { file } = activeResult;
433	    onClose();
434	    try {
435	      insertLinkAtInsertTarget({ app, file, target: insertTarget });
436	    } catch (error) {
437	      const message = error instanceof Error ? error.message : String(error);
438	      new Notice(`Could not insert a link to ${file.basename}: ${message}`);
439	    }
440	  };
441	
442	  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
443	    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
444	      // Otherwise the caret jumps to the start or end of the query.
445	      event.preventDefault();
446	      moveActiveIndex(event.key === "ArrowDown" ? 1 : -1);
447	      return;
448	    }
449	
450	    if (event.key !== "Enter") return;
451	    // Enter also commits an IME candidate, which must not open a file.
452	    if (event.nativeEvent.isComposing) return;
453	    // activeResult is part of the gate so the chord is not claimed while the
454	    // results are still loading, matching the footer button's disabled state.
455	    if (
456	      (event.metaKey || event.ctrlKey) &&
457	      !event.altKey &&
458	      insertTarget &&
459	      activeResult
460	    ) {
461	      event.preventDefault();
462	      insertLinkToActiveResult();
463	      return;
464	    }
