33	const DIRECTION_LABELS: Record<SortKey, Record<SortDirection, string>> = {
34	  relevance: { desc: "Best match first", asc: "Worst match first" },
35	  title: { asc: "A to Z", desc: "Z to A" },
36	  dateCreated: { desc: "Newest first", asc: "Oldest first" },
