50	export const getDefaultDirectionForKey = (sortKey: SortKey): SortDirection =>
51	  sortKey === "title" || sortKey === "author" ? "asc" : "desc";
52	
53	export const isDefaultSort = ({
54	  sortKey,
55	  direction,
