63	  SORT_OPTIONS.find((option) => option.key === sortKey)?.label ?? "";
64	
65	const getAuthorName = ({
66	  result,
67	  authorNameByPath,
68	}: {
69	  result: SortableSearchResult;
70	  authorNameByPath: Map<string, string> | undefined;
71	}): string => authorNameByPath?.get(result.file.path) ?? "";
