73	/** Unattributed notes sit after every named author, in both directions. */
74	const compareUnattributedLast = ({
75	  a,
76	  b,
77	  authorNameByPath,
78	}: {
79	  a: SortableSearchResult;
80	  b: SortableSearchResult;
81	  authorNameByPath: Map<string, string> | undefined;
82	}): number => {
83	  const isAUnattributed = isUnattributedAuthorName(
84	    getAuthorName({ result: a, authorNameByPath }),
85	  );
86	  const isBUnattributed = isUnattributedAuthorName(
87	    getAuthorName({ result: b, authorNameByPath }),
88	  );
89	  if (isAUnattributed === isBUnattributed) return 0;
90	  return isAUnattributed ? 1 : -1;
91	};
92	
93	const compareAscending = ({
94	  a,
95	  b,
96	  sortKey,
97	  authorNameByPath,
98	}: {
99	  a: SortableSearchResult;
100	  b: SortableSearchResult;
101	  sortKey: SortKey;
102	  authorNameByPath: Map<string, string> | undefined;
103	}): number => {
104	  if (sortKey === "relevance") return a.match.score - b.match.score;
105	  if (sortKey === "title") return a.title.localeCompare(b.title);
106	  if (sortKey === "dateCreated") return a.file.stat.ctime - b.file.stat.ctime;
107	  if (sortKey === "dateModified") return a.file.stat.mtime - b.file.stat.mtime;
108	
109	  const authorDelta = getAuthorName({
110	    result: a,
111	    authorNameByPath,
112	  }).localeCompare(getAuthorName({ result: b, authorNameByPath }));
113	  return authorDelta !== 0 ? authorDelta : a.title.localeCompare(b.title);
114	};
115	
116	/** `authorNameByPath` is only needed for the author sort. */
117	export const sortSearchResults = <T extends SortableSearchResult>({
118	  results,
119	  sortKey,
120	  direction,
121	  authorNameByPath,
122	}: {
123	  results: T[];
124	  sortKey: SortKey;
125	  direction: SortDirection;
126	  authorNameByPath?: Map<string, string>;
127	}): T[] =>
128	  [...results].sort((a, b) => {
129	    if (sortKey === "author") {
130	      // Outside the direction flip on purpose: this partition is not reversible.
131	      const unattributedDelta = compareUnattributedLast({
132	        a,
133	        b,
134	        authorNameByPath,
135	      });
136	      if (unattributedDelta !== 0) return unattributedDelta;
137	    }
138	    const delta = compareAscending({ a, b, sortKey, authorNameByPath });
139	    return direction === "asc" ? delta : -delta;
140	  });
